CHS = []

CHS.append(CH(
 "Strings, branes and Maldacena's duality",
 ("String origin", []),
 ["String theory replaces point particles with tiny vibrating strings. Closed loops of string give gravity; open strings, whose ends sit on surfaces called D-branes, give the kind of forces found in particle physics.",
  "A stack of N D-branes can be described in two ways: as a gauge theory living on the branes, or as a curved spacetime that the branes create. Maldacena realised that at low energies these two descriptions must be the same theory.",
  "The result is the AdS/CFT correspondence, with a precise map between the knobs of the gauge theory (N and the coupling) and the size and quantum-ness of the curved space."],
 [("String", "A tiny one-dimensional object whose vibrations appear as different particles."),
  ("String length ℓs", "The typical size of a string."),
  ("D-brane", "A surface on which open strings can end; a D3-brane has three space dimensions."),
  ("Gauge theory", "A quantum theory of force-carrying fields, like the theory of gluons."),
  ("N", "The number of branes, and the number of 'colours' of the gauge theory."),
  ("'t Hooft coupling λ", "λ = g²N: the effective strength of the gauge theory at large N."),
  ("N = 4 super Yang-Mills", "The highly symmetric gauge theory that lives on D3-branes; it is a CFT."),
  ("AdS5 x S5", "Five-dimensional AdS times a five-dimensional sphere: the space near the branes.")],
 ["Closed strings contain gravity; open strings on D-branes give gauge theory.",
  "N D3-branes: gauge theory SU(N) on the branes, or a curved throat AdS5 × S5.",
  "Maldacena: N = 4 super Yang-Mills = string theory on AdS5 × S5.",
  "L/ℓs = λ^(1/4): strong coupling means a big, gently curved space.",
  "G ∝ 1/N²: many colours means classical gravity."],
 [T("So far holography is a principle. To make it a precise statement you need a theory of quantum gravity in which both sides can be written down. String theory supplies it."),
  T("The starting idea of string theory is simple: what we call particles are tiny strings, and different particles are different notes on the same string. There are two kinds. Closed strings are loops. One of their vibrations has exactly the properties of the graviton, the particle of gravity, which is why string theory is a theory of gravity. Open strings have two ends. (See Figure 5.1 below.)"),
  F("holo-strings.svg", "Open strings end on D-branes and give gauge fields. Closed strings roam free and give gravity."),
  T("The ends of open strings must sit somewhere: on surfaces called D-branes, discovered to be real dynamical objects by Joseph Polchinski in 1995. A D3-brane is a brane with three dimensions of space. If you stack $N$ of them on top of each other, an open string can start on any one of the $N$ branes and end on any one, giving $N\\times N$ kinds of string. At low energies these behave exactly like the gluons of a gauge theory with $N$ colours."),
  T("Here is the crucial step. That same stack of branes can be described in two completely different ways. (See Figure 5.2 below.)"),
  F("holo-branes.svg", "Two descriptions of N D3-branes: a gauge theory, or a curved throat."),
  T("Picture one, valid when the strings interact weakly. The branes are sheets in flat space. The physics on them is a gauge theory called $\\mathcal N=4$ super Yang-Mills with gauge group $SU(N)$. This theory happens to be a conformal field theory: it has no length scale at all."),
  T("Picture two, valid when the stack is heavy. Branes have mass, and mass curves space. The stack disappears and is replaced by a curved geometry with a deep throat. Far down the throat the geometry is five-dimensional AdS times a five-dimensional sphere, written $AdS_5\\times S^5$, both with the same radius $L$."),
  T("In 1997 Juan Maldacena took the low-energy limit of both pictures. In each, the physics splits into two parts that stop talking to each other, and one part is the same in both (free gravity far away). So the other parts must be equal too:"),
  MX(r"\mathcal{N}=4 \ \text{super Yang-Mills with } SU(N) \;\;=\;\; \text{string theory on } AdS_5\times S^5"),
  T("A four-dimensional theory without gravity equals a theory of quantum gravity in a higher-dimensional curved space. The four dimensions are the boundary of the $AdS_5$. This is the holographic principle, realised exactly."),
  T("The gauge theory has two knobs: the number of colours $N$ and the coupling $g$. The string side has the size of the space $L$ in string lengths $\\ell_s$, and Newton's constant $G$ which controls quantum gravity effects. The map between them is the heart of the matter:"),
  MX(r"\frac{L^4}{\ell_s^{\,4}} = g^2 N \equiv \lambda"),
  MX(r"\frac{L^3}{G_5} = \frac{2N^2}{\pi}"),
  TB("The parameter map", ["Gauge theory", "String side", "Consequence"],
     [["'t Hooft coupling λ = g²N", "(L/ℓs)⁴", "strong coupling = space much bigger than a string"], ["number of colours N", "L³/G ∝ N²", "large N = weak quantum gravity"], ["1/N corrections", "quantum loops of gravity", "tiny when N is huge"], ["1/√λ corrections", "stringy corrections", "tiny when coupling is strong"]]),
  T("Read the first relation carefully. When the gauge theory is strongly coupled ($\\lambda$ large), where ordinary calculation is hopeless, the curved space is large and smooth and Einstein's gravity works beautifully. When the gauge theory is weakly coupled and easy, the space is so curved that strings feel it and gravity is useless. (See Figure 5.3 below.)"),
  F("holo-regimes.svg", "Each description is easy exactly where the other is hard."),
  T("This is why the duality is both powerful and hard to prove. It is powerful because it swaps a hard problem for an easy one. It is hard to prove because you can rarely compute the same thing on both sides. It has nevertheless passed every test devised in more than twenty-five years, using quantities protected by symmetry, exact methods such as integrability and localization, and computer simulation."),
  TB("Why large N is special", ["Idea", "In the gauge theory", "In the bulk"],
     [["'t Hooft's 1974 observation", "diagrams organise by the surface they can be drawn on", "the same as the loop expansion of a string theory"], ["degrees of freedom", "about N² fields", "L³/G ∝ N²: the entropy of black holes"], ["factorization", "⟨O O O O⟩ ≈ ⟨O O⟩⟨O O⟩", "bulk particles are nearly free"]])],
 [("Which strings give gravity?", ["Closed strings", "Open strings", "Neither", "Only strings on branes"], 0, "The graviton is a closed-string vibration."),
  ("What lives on a stack of N D3-branes at low energy?", ["A gauge theory with N colours", "A black hole only", "Nothing", "A single particle"], 0, "N = 4 super Yang-Mills."),
  ("What does the 't Hooft coupling λ = g²N control on the string side?", ["The size of the space in string lengths", "The number of dimensions", "The speed of light", "The colour of the branes"], 0, "L⁴/ℓs⁴ = λ."),
  ("When is classical gravity a good description?", ["Large N and large λ", "Small λ", "N = 1", "Never"], 0, "Weak quantum gravity and small strings."),
  ("Why is the duality hard to prove directly?", ["Each side is easy only where the other is hard", "It has never been tested", "String theory has no gravity", "N is unknown"], 0, "Strong-weak duality.")],
 [("Maldacena's duality", "N = 4 super Yang-Mills = strings on AdS5 × S5"), ("L and λ", "L⁴/ℓs⁴ = λ = g²N"), ("G and N", "L³/G ∝ N²"), ("Open vs closed strings", "Gauge theory vs gravity")],
 [MATCH("Gauge side and string side", "Pair each gauge-theory quantity with its partner.", [("λ = g²N", "size of space in string units"), ("N²", "inverse of Newton's constant"), ("open strings", "gauge fields"), ("closed strings", "gravity")]),
  FILL("The duality", "Open strings end on {{D-branes}}. A stack of N branes gives a gauge theory with N {{colours}}. The space near the branes is {{AdS}}5 times a five-sphere. Gravity is classical when N is {{large}}."),
  ORDER("Maldacena's argument", "Put the steps in order.", ["Take a stack of N D3-branes", "Describe it as a gauge theory on the branes", "Describe it as a curved throat geometry", "Take low energies and equate the two"])]))

CHS.append(CH(
 "The dictionary",
 ("Dictionary", []),
 ["A duality is only useful with a dictionary: a rule for translating each quantity on one side into a quantity on the other.",
  "The master rule equates the two partition functions. From it follow the pairings: a bulk field for every boundary operator, with the field's mass fixing the operator's scaling dimension.",
  "The radial depth z of the bulk is the energy scale of the boundary theory. Moving inward is a renormalization group flow."],
 [("Partition function", "The sum over all histories of a theory; it generates every correlation function."),
  ("Source", "A knob you turn to probe an operator; mathematically, the boundary value of a bulk field."),
  ("GKPW rule", "Gubser-Klebanov-Polyakov and Witten's statement that the bulk and boundary partition functions are equal."),
  ("Mass-dimension relation", "Δ(Δ − d) = m²L²."),
  ("Breitenlohner-Freedman bound", "The lowest allowed mass squared in AdS: m²L² ≥ −d²/4."),
  ("Witten diagram", "A picture of a bulk calculation of boundary correlations."),
  ("UV and IR", "Short-distance, high-energy physics (UV) and long-distance, low-energy physics (IR).")],
 ["Z_CFT[source φ0] = Z_gravity[field → φ0 at the boundary].",
  "Each boundary operator O pairs with a bulk field φ.",
  "Mass fixes dimension: Δ(Δ − d) = m²L².",
  "Near the boundary φ ≈ φ0 z^(d−Δ) + ⟨O⟩ z^Δ: source and response.",
  "Depth z is inverse energy: the boundary is the UV, the deep bulk is the IR."],
 [T("If two theories are the same, there must be a translation between them. The translation manual of AdS/CFT is called the dictionary. (See Figure 6.1 below.)"),
  F("holo-dictionary.svg", "The holographic dictionary: each bulk object has a boundary partner."),
  T("The master entry was written down in 1998 by Gubser, Klebanov and Polyakov, and by Witten. In a quantum field theory you learn everything by poking it: add a source $\\phi_0(x)$ coupled to an operator $O(x)$ and see how the theory responds. All the responses are packed into the partition function $Z_{CFT}[\\phi_0]$. The rule is"),
  MX(r"Z_{CFT}[\phi_0] \;=\; Z_{gravity}\big[\phi \to \phi_0 \text{ at the boundary}\big] \;\approx\; e^{-S_{gravity}[\phi_{classical}]}"),
  T("In words: turning a knob in the boundary theory is the same as fixing the value of a bulk field at the edge of AdS. When gravity is classical (large $N$, large $\\lambda$) the right-hand side is easy: solve the classical field equations with that boundary value and evaluate the action."),
  T("So every operator has a partner field. What decides which operator? Solve the wave equation for a field of mass $m$ in AdS and look near the boundary $z\\to0$. There are always two behaviours:"),
  MX(r"\phi(z,x) \;\approx\; \phi_0(x)\, z^{\,d-\Delta} \;+\; \langle O(x)\rangle\, z^{\,\Delta}"),
  MX(r"\Delta(\Delta - d) = m^2L^2"),
  T("The slowly falling piece is the source $\\phi_0$, the knob you control. The fast falling piece is the response: its coefficient is (up to a constant) the expectation value $\\langle O\\rangle$ of the dual operator. And the number $\\Delta$ that appears, fixed by the mass, is exactly the operator's scaling dimension."),
  TB("Mass and dimension for a four-dimensional boundary (d = 4)", ["m²L²", "Δ", "Example"],
     [["−4", "2", "the lowest allowed mass (Breitenlohner-Freedman bound)"], ["−3", "3", "a relevant operator, such as a mass term"], ["0", "4", "the dilaton, dual to the gauge kinetic term Tr F²"], ["5", "5", "an irrelevant operator"], ["12", "6", "heavier field, higher dimension"]]),
  T("Notice that slightly negative $m^2$ is allowed. In flat space a negative mass squared means instability. In AdS the curvature helps, and the field is stable as long as $m^2L^2 \\ge -d^2/4$, the Breitenlohner-Freedman bound. Below it, $\\Delta$ would be complex and no sensible operator exists."),
  TB("The main dictionary entries", ["Bulk", "Boundary", "Comment"],
     [["scalar field φ", "scalar operator O", "mass ↔ dimension"], ["metric g", "stress tensor T", "gravity ↔ energy and momentum"], ["gauge field A", "conserved current J", "bulk gauge symmetry ↔ boundary global symmetry"], ["boundary value of a field", "source for the operator", "the knob"], ["classical action", "generating function of correlators", "at large N"], ["black hole", "thermal state", "chapter 8"], ["minimal surface", "entanglement entropy", "chapter 7"]]),
  T("To compute how operators are correlated, differentiate with respect to the sources. In the bulk this becomes a sum of pictures called Witten diagrams: lines running from boundary points into the bulk, meeting at interaction points that are integrated over all of AdS. (See Figure 6.2 below.)"),
  F("holo-witten.svg", "Witten diagrams for two-, three- and four-point functions."),
  T("The simplest diagram, a single line between two boundary points, reproduces the power law $1/|x|^{2\\Delta}$ of chapter 4. That is a real check: a calculation in curved space gives the answer that conformal symmetry demands."),
  T("Finally, the meaning of the extra dimension. Recall that scaling $(t,x,z)$ together is a symmetry. A blob of size $z$ deep in the bulk corresponds to an excitation of size $z$ in the boundary theory. Small $z$ means fine detail and high energy; large $z$ means coarse features and low energy. (See Figure 6.3 below.)"),
  F("holo-rgdepth.svg", "The radial direction is energy scale. Moving inward blurs out detail."),
  MX(r"E \sim \frac{1}{z}"),
  T("Physicists call the process of zooming out and keeping only coarse features the renormalization group, RG. Holography turns RG into geometry: one step of RG is one step into the bulk. If the bulk ends at some depth, a wall or a horizon, the boundary theory has a lowest energy scale: a mass gap, or a temperature. This idea is the bridge to tensor networks in chapter 9 and to deep learning in chapter 11.")],
 [("What does the GKPW rule equate?", ["The partition functions of the two theories", "Their dimensions", "Their temperatures", "Their colours"], 0, "With sources as boundary values."),
  ("A bulk field's boundary value plays the role of...", ["a source for the dual operator", "the temperature", "the central charge", "a black hole"], 0, "The knob."),
  ("What fixes an operator's scaling dimension?", ["The mass of the dual bulk field", "The number of branes only", "The boundary's shape", "Nothing"], 0, "Δ(Δ − d) = m²L²."),
  ("What is dual to the metric?", ["The stress tensor", "A scalar operator", "A current", "The entropy"], 0, "Gravity ↔ energy-momentum."),
  ("Where is the high-energy (UV) physics of the boundary theory?", ["Near the boundary, small z", "Deep in the bulk", "At the horizon", "Nowhere"], 0, "E ~ 1/z.")],
 [("GKPW", "Z_CFT[φ0] = Z_gravity[φ → φ0]"), ("Mass ↔ dimension", "Δ(Δ − d) = m²L²"), ("Near-boundary field", "φ ≈ φ0 z^(d−Δ) + ⟨O⟩ z^Δ"), ("Depth and energy", "E ~ 1/z: boundary = UV, deep bulk = IR")],
 [MATCH("Bulk and boundary", "Pair each bulk object with its boundary partner.", [("metric", "stress tensor"), ("gauge field", "conserved current"), ("mass", "scaling dimension"), ("depth z", "inverse energy")]),
  FILL("Dictionary", "The boundary value of a bulk field is a {{source}}. The mass of the field fixes the scaling {{dimension}}. A massless scalar with d = 4 has Δ = {{4}}. The boundary is the {{UV}} of the field theory."),
  ORDER("Compute a correlator with gravity", "Put the steps in order.", ["Choose the operator and find its dual field", "Fix the field's boundary value (the source)", "Solve the bulk equations", "Differentiate the action with respect to the source"])]))

CHS.append(CH(
 "Entanglement builds geometry",
 ("Entanglement", []),
 ["In 2006 Ryu and Takayanagi found the dictionary entry for entanglement: the entanglement entropy of a boundary region equals the area of the smallest bulk surface that ends on it, divided by 4G.",
  "The formula has the same shape as black hole entropy, but it works for any region. It reproduces the logarithmic law of two-dimensional CFTs and makes hard entropy inequalities obvious.",
  "It also suggests something radical: the connectedness of space is made of entanglement. Remove the entanglement and space comes apart."],
 [("Ryu-Takayanagi (RT) formula", "S(A) = Area(γ_A)/4G, with γ_A the minimal bulk surface anchored on the edge of A."),
  ("Minimal surface", "The surface of least area with a given boundary; in AdS3, a geodesic."),
  ("Homology condition", "The requirement that the surface, together with A, encloses a bulk region."),
  ("Entanglement wedge", "The bulk region between A and its RT surface."),
  ("HRT surface", "The version of the RT surface for situations that change in time (Hubeny, Rangamani, Takayanagi)."),
  ("Quantum extremal surface", "The surface that extremises area/4G plus the bulk entanglement entropy.")],
 ["RT: S(A) = Area(γ_A)/4G for the minimal surface anchored on A.",
  "In AdS3 the surface is a geodesic of length 2L ln(ℓ/ε), giving S = (c/3) ln(ℓ/ε) with c = 3L/2G.",
  "The minimal surface can jump between competing shapes: a phase transition in entanglement.",
  "Quantum correction: S = Area/4G + S_bulk.",
  "Less entanglement between two boundary parts means a thinner bulk connection (Van Raamsdonk)."],
 [T("The dictionary of the last chapter translates fields and operators. But the boundary theory is a quantum system with a huge amount of entanglement. What does entanglement look like in the bulk? In 2006 Shinsei Ryu and Tadashi Takayanagi proposed a strikingly simple answer. (See Figure 7.1 below.)"),
  F("holo-rt.svg", "The Ryu-Takayanagi formula: entropy of region A is the area of the minimal surface γ_A over 4G."),
  MX(r"S(A) \;=\; \frac{\mathrm{Area}(\gamma_A)}{4G}"),
  T("Take a region $A$ of the boundary at one moment of time. Among all bulk surfaces that end on the edge of $A$ (and can be smoothly pushed onto $A$), find the one with the smallest area, $\\gamma_A$. Its area in Planck units, divided by four, is the entanglement entropy of $A$ with the rest of the boundary."),
  T("This looks just like the black hole formula $S = A/4G$ from chapter 1, and that is no accident: for a thermal state the minimal surface wraps the horizon, and the formula becomes Bekenstein and Hawking's. Ryu-Takayanagi is the generalisation of black hole entropy to any region."),
  T("Let us test it where we know the answer. Take $AdS_3$, whose boundary is one-dimensional, so region $A$ is an interval of length $\\ell$ and a 'surface' is just a curve. The minimal curve is a geodesic, the semicircle of chapter 2. Its length is infinite, because the boundary is infinitely far away, so we stop at a small depth $z=\\epsilon$:"),
  MX(r"\mathrm{Length}(\gamma_A) = 2L\,\ln\frac{\ell}{\epsilon}"),
  MX(r"\Longrightarrow"),
  MX(r"S(A) = \frac{L}{2G}\,\ln\frac{\ell}{\epsilon} = \frac{c}{3}\,\ln\frac{\ell}{\epsilon}"),
  T("The last step uses a result from 1986 by Brown and Henneaux: gravity in $AdS_3$ has the symmetries of a two-dimensional CFT with central charge $c = 3L/2G$. So the geometric calculation gives exactly the logarithmic law of chapter 4. The mysterious logarithm is the length of a curve in hyperbolic space, and the cutoff $\\epsilon$ is where we stop near the boundary."),
  TB("What the RT formula makes easy", ["Property", "In quantum theory", "In the bulk picture"],
     [["S(A) = S(rest) for a pure state", "a theorem about pure states", "A and its complement share the same minimal surface"], ["subadditivity", "S(AB) ≤ S(A) + S(B)", "the surface for AB is at most the two surfaces together"], ["strong subadditivity", "notoriously hard to prove", "cut and re-glue two surfaces: a one-line picture proof"], ["UV divergence, area law", "entanglement across the edge of A", "the surface runs out to the infinitely distant boundary"]]),
  T("The minimal surface is found by a competition, and competitions can have sudden changes of winner. Take two separate intervals. Either each gets its own curve, or two curves bridge between them. (See Figure 7.2 below.)"),
  F("holo-twointervals.svg", "For two regions, the minimal surface jumps from separate curves to bridging curves as the regions grow."),
  T("When the intervals are small and far apart, separate curves win, and the mutual information $I(A:B)=S(A)+S(B)-S(AB)$ is zero at this order. Enlarge them and the bridging curves become shorter: the bulk region belonging to $A\\cup B$, its entanglement wedge, suddenly becomes connected, and the mutual information turns on. You will find this switch in the lab."),
  T("The formula has since been extended. Hubeny, Rangamani and Takayanagi (2007) gave the version for geometries that change in time, using extremal instead of minimal surfaces. Faulkner, Lewkowycz and Maldacena (2013) added the first quantum correction: the entanglement of the bulk fields themselves across the surface."),
  MX(r"S(A) \;=\; \frac{\mathrm{Area}(\gamma_A)}{4G} \;+\; S_{bulk}(\text{entanglement wedge of } A) \;+\;\dots"),
  T("Engelhardt and Wall (2014) then proposed that the right surface is the one that extremises this whole sum, the quantum extremal surface. Keep this in mind: it is the tool that resolves the black hole information puzzle in chapter 12."),
  TB("The family of entropy formulas", ["Year", "Formula", "Valid for"],
     [["1973-75", "S = A/4G (Bekenstein, Hawking)", "black hole horizons"], ["2006", "S(A) = min Area/4G (Ryu, Takayanagi)", "static geometries, any region"], ["2007", "extremal surface (HRT)", "time-dependent geometries"], ["2013", "+ S_bulk (FLM)", "first quantum correction"], ["2014", "extremise Area/4G + S_bulk (quantum extremal surface)", "all orders"]]),
  T("Now turn the formula around. If entanglement is measured by area, then geometry is made of entanglement. Mark Van Raamsdonk made this vivid in 2010. Divide the boundary into two halves and imagine reducing the entanglement between them. By RT the surface separating the two halves of the bulk must shrink. At the same time the mutual information between distant points drops, which means they get further apart. The space stretches and pinches. (See Figure 7.3 below.)"),
  F("holo-pinch.svg", "As entanglement between two halves is removed, the space joining them pinches off."),
  T("With no entanglement at all you have two separate universes. Space is not a stage on which the quantum system sits. It is a picture of how the system's parts are entangled. The rest of the course is about making that sentence precise.")],
 [("What does the RT formula compute?", ["The entanglement entropy of a boundary region", "The mass of a black hole", "The number of branes", "The speed of light"], 0, "From a minimal bulk surface."),
  ("In AdS3, the RT 'surface' for an interval is...", ["a geodesic", "a sphere", "the horizon", "a point"], 0, "A curve of minimal length."),
  ("Which central charge does AdS3 gravity have?", ["c = 3L/2G", "c = 1", "c = N", "c = 0"], 0, "Brown and Henneaux."),
  ("What happens to the minimal surface of two intervals as they grow?", ["It jumps to a bridging configuration", "Nothing", "It disappears", "It becomes a horizon"], 0, "An entanglement phase transition."),
  ("What did Van Raamsdonk argue?", ["Removing entanglement disconnects space", "Entanglement is unrelated to geometry", "Black holes have no entropy", "AdS is flat"], 0, "Space is built from entanglement.")],
 [("RT formula", "S(A) = Area(γ_A) / 4G"), ("AdS3 check", "Geodesic length 2L ln(ℓ/ε) gives (c/3) ln(ℓ/ε), c = 3L/2G"), ("Quantum correction", "S = Area/4G + S_bulk"), ("Van Raamsdonk", "Entanglement holds space together")],
 [MATCH("Formula and author", "Pair each formula with its origin.", [("S = A/4G for horizons", "Bekenstein and Hawking"), ("minimal surface", "Ryu and Takayanagi"), ("c = 3L/2G", "Brown and Henneaux"), ("+ S_bulk", "Faulkner, Lewkowycz, Maldacena")]),
  FILL("RT", "The entropy of a boundary region is the {{area}} of the minimal bulk surface over {{4}}G. In AdS3 that surface is a {{geodesic}}. Removing entanglement makes space {{disconnect}}."),
  ORDER("Apply the RT formula", "Put the steps in order.", ["Choose a boundary region A", "Find all bulk surfaces ending on its edge", "Pick the one with the smallest area", "Divide the area by 4G"])]))

CHS.append(CH(
 "Black holes, temperature and wormholes",
 ("Black holes", []),
 ["Heat the boundary theory and a black hole forms in the bulk. Its temperature is the temperature of the boundary theory, and its horizon area is the thermal entropy.",
  "Below a critical temperature the black hole is not the preferred geometry: the Hawking-Page transition, which the boundary theory sees as the change from confined to deconfined matter.",
  "Two copies of the boundary theory in a special entangled state describe a single black hole with two outsides joined by a wormhole. Entanglement is the bridge."],
 [("Hawking temperature", "The temperature at which a black hole radiates."),
  ("BTZ black hole", "The black hole of three-dimensional AdS gravity."),
  ("Thermal state", "A system in equilibrium at a temperature T; a mixed state."),
  ("Hawking-Page transition", "The switch between thermal AdS and a black hole as the dominant geometry."),
  ("Thermofield double (TFD)", "An entangled state of two copies of a system in which each copy alone is thermal."),
  ("Einstein-Rosen bridge", "The wormhole connecting the two sides of an eternal black hole."),
  ("ER = EPR", "The slogan that wormholes (ER) and entanglement (EPR) are the same thing.")],
 ["Thermal state of the CFT ↔ black hole in AdS; horizon area/4G = thermal entropy.",
  "BTZ: T = r_h/(2πL²), S = 2πr_h/4G, matching the CFT's Cardy formula.",
  "Hawking-Page: below T = 1/(2πL) thermal AdS wins; above it the black hole wins.",
  "With a horizon, S(A) ≠ S(rest); the difference for large A is the black hole entropy.",
  "Thermofield double = eternal two-sided black hole; the entanglement is the wormhole."],
 [T("What is a black hole in the boundary theory? There is no gravity there, so it cannot be a black hole. The dictionary answer is beautifully simple: a black hole in the bulk is the boundary theory at a temperature. Hot soup."),
  T("The reasoning: a black hole has a temperature (Hawking) and an entropy (Bekenstein). A quantum system with a temperature and an entropy is a thermal state. The energy of the black hole is the energy of the hot matter, and the area of the horizon divided by $4G$ is its entropy."),
  T("The cleanest example is the black hole of three-dimensional AdS gravity, found by Bañados, Teitelboim and Zanelli (BTZ) in 1992:"),
  MX(r"ds^2 = -\frac{r^2 - r_h^2}{L^2}\,dt^2 + \frac{L^2}{r^2 - r_h^2}\,dr^2 + r^2\,d\phi^2"),
  T("The horizon is at $r = r_h$, where the coefficient of $dt^2$ vanishes: time stands still there for an outside observer. Its temperature and entropy are"),
  MX(r"T = \frac{r_h}{2\pi L^2}"),
  MX(r"S = \frac{2\pi r_h}{4G} = \frac{\pi c}{3}\,(2\pi L)\,T"),
  T("The last form uses $c = 3L/2G$. It says the entropy is $\\pi c/3$ times the length of the boundary circle, $2\\pi L$, times the temperature. That is exactly Cardy's formula for the entropy of any two-dimensional CFT at high temperature. Gravity counts the CFT's states correctly."),
  TB("Black hole and hot matter", ["Bulk (black hole)", "Boundary (thermal state)"],
     [["Hawking temperature", "temperature T"], ["horizon area / 4G", "thermal entropy"], ["mass", "energy"], ["something falls in and the hole rings down", "a disturbance thermalises"], ["horizon cloaks the interior", "the state is mixed: information is spread out"]]),
  T("Is a black hole always the right bulk description of a hot state? No. Hawking and Page showed in 1983 that there are two competing geometries with the same temperature at the boundary: empty AdS filled with a gas of hot particles (thermal AdS), and a black hole. The one with the lower free energy $F$ wins. (See Figure 8.1 below.)"),
  F("holo-hp.svg", "The Hawking-Page transition: thermal AdS at low temperature, a black hole at high temperature."),
  T("In three dimensions the switch happens at $T = 1/(2\\pi L)$. Witten pointed out in 1998 what this means for the gauge theory: at low temperature its entropy is small (the colour charges are confined into a few bound states), while at high temperature it jumps to order $N^2$ (the $N^2$ gluons are set free). The formation of a black hole is deconfinement."),
  T("A horizon changes entanglement. For a small region the RT curve stays outside the horizon and barely notices it. For a large region it becomes cheaper to take the short curve around the complement and add the whole horizon. (See Figure 8.2 below.)"),
  F("holo-btz.svg", "RT curves in a black hole geometry. Large regions pay for the horizon."),
  MX(r"S(\ell) = \frac{c}{3}\,\ln\!\left(\frac{\beta}{\pi\epsilon}\,\sinh\frac{\pi \ell}{\beta}\right)"),
  MX(r"\beta = \frac1T"),
  T("For $\\ell$ much smaller than $\\beta$ this is the old logarithm. For $\\ell$ much larger it grows in proportion to $\\ell$: a volume law, as a thermal state should have. And because the state is mixed, $S(A)$ no longer equals $S(\\bar A)$. For large $A$ the difference is exactly the black hole entropy."),
  T("Where did the purity go? A thermal state is mixed, but any mixed state can be seen as half of a pure entangled state of a bigger system. Take two copies of the CFT, call them left and right, in the thermofield double state:"),
  MX(r"|TFD\rangle = \frac{1}{\sqrt{Z}}\sum_n e^{-\beta E_n/2}\,|n\rangle_L\,|n\rangle_R"),
  T("Each copy alone is exactly thermal. In 2001 Maldacena proposed that the bulk dual is the eternal black hole: one geometry with two outside regions, each with its own boundary, joined through the interior by an Einstein-Rosen bridge, a wormhole. (See Figure 8.3 below.)"),
  F("holo-tfd.svg", "The thermofield double state is dual to a two-sided black hole. The entanglement is the bridge."),
  T("The two CFTs do not interact at all. They are only entangled. Yet in the bulk their spaces are joined. The RT surface between left and right is the horizon, and its area is the entanglement entropy between the two copies. Maldacena and Susskind compressed this in 2013 into the slogan ER = EPR: Einstein-Rosen bridges and Einstein-Podolsky-Rosen entanglement are two descriptions of one thing. The bridge cannot be used to send signals, just as entanglement cannot."),
  TB("One-sided and two-sided pictures", ["", "One CFT", "Two entangled CFTs"],
     [["state", "thermal (mixed)", "thermofield double (pure)"], ["bulk", "black hole seen from outside", "eternal black hole with two outsides"], ["horizon area/4G", "thermal entropy", "entanglement entropy between left and right"], ["connection", "none needed", "a wormhole that cannot be crossed"]])],
 [("What is a bulk black hole in the boundary theory?", ["A thermal state", "A single particle", "The vacuum", "A boundary black hole"], 0, "Hot matter."),
  ("What is the horizon area divided by 4G?", ["The thermal entropy", "The temperature", "The energy", "The central charge"], 0, "Bekenstein-Hawking."),
  ("Below the Hawking-Page temperature, which geometry dominates?", ["Thermal AdS", "A big black hole", "Flat space", "A wormhole"], 0, "Lower free energy."),
  ("With a horizon, how does S(ℓ) grow for large regions?", ["In proportion to ℓ (volume law)", "Logarithmically", "It stays constant", "It decreases"], 0, "Thermal entropy."),
  ("What is the bulk dual of the thermofield double state?", ["A two-sided eternal black hole", "Empty AdS", "Two unconnected universes", "A single particle"], 0, "Joined by a wormhole.")],
 [("Black hole ↔ thermal state", "Area/4G = thermal entropy, T_Hawking = T"), ("Hawking-Page", "Thermal AdS below T = 1/(2πL), black hole above"), ("TFD", "Σ e^(−βE/2) |n⟩|n⟩: each side thermal, whole pure"), ("ER = EPR", "Wormhole = entanglement")],
 [MATCH("Bulk and boundary", "Pair each bulk feature with its boundary meaning.", [("horizon area / 4G", "thermal entropy"), ("black hole forms", "deconfinement"), ("wormhole", "entanglement between two copies"), ("ringdown", "thermalisation")]),
  FILL("Black holes", "A black hole in the bulk is a {{thermal}} state on the boundary. The Hawking-{{Page}} transition switches between thermal AdS and a black hole. The thermofield double is dual to a {{two}}-sided black hole joined by a {{wormhole}}."),
  ORDER("From cold to hot", "Put the steps in order.", ["Vacuum: empty AdS", "Low temperature: thermal gas in AdS", "Hawking-Page temperature: free energies cross", "High temperature: a black hole dominates"])]))

CHS.append(CH(
 "Tensor networks: holograms you can count",
 ("Tensor networks", []),
 ["A tensor network builds a big quantum state out of small pieces joined by bonds. The pattern of bonds controls the pattern of entanglement.",
  "Coarse-graining a quantum system step by step produces a layered network with an extra direction: scale. For a critical system the network has the shape of hyperbolic space, and the entropy of a region is bounded by the cheapest cut through the bonds, a discrete Ryu-Takayanagi formula.",
  "Special networks built from 'perfect' or random tensors make this exact, and they are also error-correcting codes. They are toy models: simple enough to count, rich enough to show how holography works."],
 [("Tensor", "A block of numbers with several indices, drawn as a shape with legs."),
  ("Bond", "A leg shared by two tensors; it carries entanglement."),
  ("Bond dimension χ", "The number of values a bond index can take; a bond carries at most log χ of entanglement."),
  ("Renormalization (coarse-graining)", "Replacing groups of sites by fewer effective sites, keeping long-distance physics."),
  ("MERA", "Multiscale entanglement renormalization ansatz: a layered network for critical states."),
  ("Min-cut", "The smallest set of bonds whose removal separates a region from the rest."),
  ("Perfect tensor", "A tensor that is maximally entangled across every equal split of its legs."),
  ("Random tensor network", "A network whose tensors are chosen at random; its entropies obey a minimal-cut rule.")],
 ["A tensor network's bonds limit entanglement: S(A) ≤ (bonds cut) × log χ.",
  "Coarse-graining adds a direction: N sites need about log N layers.",
  "MERA reproduces S ∝ log ℓ; its shape resembles a slice of AdS (Swingle 2009).",
  "Random and perfect-tensor networks saturate the bound: entropy = minimal cut, a discrete RT formula.",
  "They are toy models: discrete, without full dynamics, but exactly solvable."],
 [T("A quantum state of $n$ qubits needs $2^n$ numbers. For 300 qubits that is more numbers than atoms in the visible universe. Tensor networks are a way to write interesting states with far fewer numbers, by building them out of small blocks."),
  T("A tensor is just a block of numbers with several indices. Draw it as a dot or box with one leg per index. Joining two legs means summing over that index. A leg joined between two tensors is called a bond; a leg left dangling is a physical qubit. The key fact: a bond that can take $\\chi$ values can carry at most $\\log\\chi$ of entanglement. So to see how entangled a region can be, count the bonds you must cut to separate it:"),
  MX(r"S(A) \;\le\; (\text{number of bonds cut}) \times \log\chi"),
  T("Now the idea that creates an extra dimension. To understand a big system, physicists coarse-grain: replace each pair of neighbouring sites by one effective site that keeps only what matters at larger distances, and repeat. Each round halves the number of sites. (See Figure 9.1 below.)"),
  F("holo-blocks.svg", "Repeated coarse-graining stacks into a tree. Its height is a new direction: scale."),
  T("Read the tree upside down and it is a recipe for building the state: start from a few coarse sites and add detail layer by layer. The layers are a new direction, and it measures scale, exactly like the depth $z$ in AdS. A system of $N$ sites needs about $\\log_2 N$ layers."),
  T("A plain tree loses too much entanglement between neighbouring blocks. Guifré Vidal's MERA (2007) fixes this by adding extra tensors that remove short-range entanglement before each coarse-graining step. The result describes critical states very well. Now cut out a block of $\\ell$ sites. (See Figure 9.2 below.)"),
  F("holo-mera.svg", "In a layered network, the cheapest cut around a block of sites climbs to the sparse upper layers."),
  T("The cheapest cut does not hug the block. It rises through the layers, where there are fewer bonds, and comes down the other side, cutting a couple of bonds per layer over about $\\log\\ell$ layers. So $S \\propto \\log\\ell$: the logarithmic law of a critical system, from pure counting."),
  T("In 2009 Brian Swingle pointed out that this is the Ryu-Takayanagi formula in disguise. The network is a discrete picture of a slice of AdS; the cheapest cut is the minimal surface; cutting more bonds is having more area. Hyperbolic space is simply the shape a network must have to hold the entanglement of a scale-invariant state."),
  TB("Network shape and entanglement", ["State", "Network", "Cheapest cut for ℓ sites", "Geometry"],
     [["gapped (short-range entangled)", "a few layers only", "constant", "a thin shell: the bulk ends"], ["critical (CFT ground state)", "log N layers, self-similar", "about log ℓ", "hyperbolic, like AdS"], ["thermal", "layers stop at a 'horizon'", "about ℓ for large blocks", "black hole"]]),
  T("A general network only gives an upper bound on entropy. Two special constructions turn the bound into an equality, a true discrete RT formula."),
  T("The first uses perfect tensors: tensors so evenly entangled that any half of their legs is maximally entangled with the other half. In 2015 Pastawski, Yoshida, Harlow and Preskill tiled the hyperbolic plane with six-leg perfect tensors, one per pentagon. Five legs join the neighbours; the sixth points out of the page and is a bulk qubit. The legs left at the rim are the boundary. (See Figure 9.3 below.)"),
  F("holo-happy.svg", "The HaPPY code: perfect tensors on a pentagon tiling of the hyperbolic plane."),
  T("This is called the HaPPY code after its authors. In it, the entropy of a connected boundary region is exactly the number of bonds on the minimal cut. And it is more than a state: it is a map from bulk qubits to boundary qubits, an error-correcting code. That is the subject of the next chapter."),
  T("The second construction uses random tensors (Hayden, Nezami, Qi, Thomas, Walter and Yang, 2016). If every tensor is chosen at random and the bond dimension is large, the entropy of any boundary region is, to excellent accuracy, the minimal cut times $\\log\\chi$. The calculation maps the network onto a simple magnet, an Ising model whose couplings are set by the bond dimensions. Hold on to that fact: an Ising model with adjustable couplings is a kind of neural network, and that is the bridge of chapter 11."),
  TB("Three network models", ["Model", "Entropy rule", "Strength", "Limitation"],
     [["MERA", "S ≤ cut × log χ", "accurate for real critical systems", "only a bound; the geometry is debated"], ["HaPPY code", "S = minimal cut (connected regions)", "exact, and an explicit code", "state is too simple: no power-law correlations"], ["random tensor network", "S = minimal cut × log χ at large χ", "any geometry, quantum corrections included", "no dynamics; flat entanglement spectrum"]]),
  T("A caution. These are toy models. They capture how entanglement and geometry fit together on one slice of time, but they do not contain gravity's dynamics, and they are discrete where AdS is smooth. Their value is that you can count everything, as you will in the lab.")],
 [("What limits the entanglement a bond can carry?", ["Its bond dimension: at most log χ", "Its colour", "Its length on the page", "Nothing"], 0, "One bond, log χ."),
  ("How many coarse-graining layers does a system of N sites need?", ["About log N", "N", "N²", "One"], 0, "Each layer halves the sites."),
  ("In a MERA, the cheapest cut around ℓ sites cuts about...", ["log ℓ bonds", "ℓ bonds", "ℓ² bonds", "zero bonds"], 0, "It climbs the layers."),
  ("What makes the entropy bound exact in the HaPPY code?", ["Perfect tensors", "Larger pages", "Hot temperature", "Extra dimensions"], 0, "Maximal entanglement across every split."),
  ("What do random tensor network entropies map to?", ["An Ising model", "A gas of strings", "A black hole only", "Nothing simple"], 0, "With couplings from bond dimensions.")],
 [("Cut bound", "S(A) ≤ bonds cut × log χ"), ("MERA and AdS", "Layers = scale; min-cut = RT surface (Swingle 2009)"), ("HaPPY code", "Perfect tensors on a hyperbolic tiling; exact RT; a code"), ("Random tensor networks", "S = min-cut × log χ; maps to an Ising model")],
 [MATCH("Network and feature", "Pair each idea with its feature.", [("bond", "carries at most log χ"), ("MERA", "log law for critical states"), ("perfect tensor", "maximally entangled across every split"), ("min-cut", "discrete RT surface")]),
  FILL("Networks", "Entropy is bounded by the number of {{bonds}} cut. N sites need about {{log}} N layers. The network of a critical state looks like {{hyperbolic}} space. The HaPPY code is built from {{perfect}} tensors."),
  ORDER("Find a region's entropy in a network", "Put the steps in order.", ["Choose boundary sites A", "List the cuts that separate A from the rest", "Pick the cut with the smallest total bond weight", "That weight is the entropy"])]))
